[
  {
    "path": "tools.linear.get_issue_status",
    "description": "Retrieve detailed information about an issue status in Linear by name or ID",
    "signature": "tools.linear.get_issue_status({
  /** Status ID */
  id: string,
  /** Status name */
  name: string,
  /** Team name or ID */
  team: string,
}): Promise<unknown>"
  },
  {
    "path": "tools.linear.get_issue",
    "description": "Retrieve detailed information about an issue by ID, including attachments, git branch name, and active Triage Intelligence suggestions when the issue is in triage. A nonempty fields selection overrides the include options; request optional fields directly in fields.",
    "signature": "tools.linear.get_issue({
  /** Issue ID or identifier (e.g., LIN-123). P-prefixed identifiers (e.g., P-ENG-123) are projects, not issues */
  id: string,
  /**
   * Fields to include in each result. Explicitly requested fields with no value return null. `id` is always included. Omit or pass an empty array for the default response.
   */
  fields?: Array<"id" | "uuid" | "title" | "description" | "projectMilestone" | "priority" | "estimate" | "url" | "gitBranchName" | "createdAt" | "updatedAt" | "archivedAt" | "completedAt" | "startedAt" | "canceledAt" | "startedTriageAt" | "triagedAt" | "dueDate" | "slaStartedAt" | "slaMediumRiskAt" | "slaHighRiskAt" | "slaBreachesAt" | "slaType" | "status" | "statusType" | "labels" | "triageIntel" | "createdBy" | "createdById" | "assignee" | "assigneeId" | "delegate" | "delegateId" | "project" | "projectId" | "parentId" | "team" | "teamId" | "cycleId" | "attachments" | "documents" | "stateHistory" | "relations" | "customerNeeds" | "releases">,
  /** Include blocking/related/duplicate relations. @default false */
  includeRelations?: boolean,
  /** Include associated customer needs. @default false */
  includeCustomerNeeds?: boolean,
  /** Include associated releases. @default false */
  includeReleases?: boolean,
}): Promise<unknown>"
  },
  {
    "path": "tools.linear.get_attachment",
    "description": "Retrieve an issue attachment by ID. Use format=url to get its title and download URL without fetching the file content. Linear upload URLs are signed for five minutes; call again to refresh. External URLs are returned unchanged. Files embedded in comments have no issue attachment ID; use the URLs in list_comments attachments instead. Download and process documents with your own file tools.",
    "signature": "tools.linear.get_attachment({
  /** Issue attachment ID from get_issue's attachments array (attachments[].id) */
  id: string,
  /**
   * Omit or use content to fetch a Linear-hosted file. Use url for attachment metadata without fetching the file; also supports external links
   */
  format?: "content" | "url",
}): Promise<unknown>"
  },
  {
    "path": "tools.linear.get_template",
    "description": "Retrieve a Linear template by ID or name: the content it pre-fills, the ids it applies, its sub-issues, and its form fields. Pass the template to save_issue or save_project to apply it. References come back as ids, so read a name with the matching tool when you need one. A form template collects its answers through a form, so applying one here creates an issue with the form unanswered.",
    "signature": "tools.linear.get_template({
  /** Template ID or name */
  id: string,
}): Promise<unknown>"
  },
  {
    "path": "tools.linear.get_triage_responsibility",
    "description": "Retrieve who is responsible for a team's triage: the person on triage now, what happens when an issue enters triage, and the upcoming shifts of the team's triage rotation. Pass `user` to get only that person's shifts, for example to find when their next triage duty starts, even when it is weeks away.",
    "signature": "tools.linear.get_triage_responsibility({
  /** Team name or ID */
  team: string,
  /** Only return shifts of this user: User ID, name, email, or "me" */
  user?: string,
  /** Max upcoming shifts to return (default 10, max 50). @default 10 @integer @minimum 1 @maximum 50 */
  limit?: number,
}): Promise<unknown>"
  }
]

